mapper.select:
SELECT
p.id AS problemId,
p.problem_name AS problemName,
p.difficulty,
CASE
WHEN #{userId} IS NULL THEN 'UNATTEMPTED'
ELSE COALESCE(upp.status, 'UNATTEMPTED')
END AS status
FROM problem p
LEFT JOIN user_problem_progress upp ON upp.problem_id = p.id AND upp.user_id = #{userId}
WHERE p.status = #{publishStatus}


    AND (
    p.problem_name LIKE CONCAT('%', #{dto.keyword}, '%')
    OR CAST(p.id AS CHAR) = #{dto.keyword}
    )



    AND p.difficulty >= #{dto.difficultyMin}



    AND p.difficulty <= #{dto.difficultyMax}



    AND (
            (#{dto.solveStatus} = 'UNATTEMPTED' AND upp.id IS NULL)
        OR
            (#{dto.solveStatus} != 'UNATTEMPTED' AND upp.status = #{dto.solveStatus})
        )


ORDER BY p.id ASC
